	[3]={ model="6105", name="Mighty Maiden", english="Corina", story="An infected human girl wears a comfortable, loose dress. She might have once been innocent and lively or gentle and introverted, but after contamination and mutation, she lost her humanity, now only violent and cruel. If you feel mercy for her, please handle her swiftly and try not to dirty her dress.", hero_type=1, shadow="mon_archives_normal_6105.png", shadow_unlock="mon_archives_shadow_6105.png", dangerous=1, skill_list={298380,300086,3007}, type=3, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
