	[16]={ model="6130_h", name="Heatwave", english="DAVIST", story="Humans who have mutated after being eroded by the Void Expanse, have lost the basic biological characteristics of humans. The middle of their bodies is damaged due to high heat, which can even cause visual distortion, but this area is the core source of all their energy. —Why their bodies emit high heat is still under investigation, with initial speculation suggesting it is caused by the surrounding environment during their mutation.", hero_type=5, shadow="mon_archives_normal_6130.png", shadow_unlock="mon_archives_shadow_6130.png", dangerous=2, skill_list={298780,304683,304686,3046,304601}, type=3, special="Focus Back Row", speed="", element={0}, weak_point={0,3}
