	[18]={ model="6309", name="Reina", english="DAVIST", story="A former senior researcher at Neoscope Inc and a biology professor at Lissugen University, turned into a monster called the [Flower of Resentment] after being injected with a certain drug. Her withered body has a kind of flawed beauty, and from the remaining human traits, she seems to still retain some human reason and rationality. But be sure not to go near her—unless you want to be torn apart by her claws.", hero_type=6, shadow="mon_archives_normal_6309.png", shadow_unlock="mon_archives_shadow_6309.png", dangerous=3, skill_list={305280,305290,305283,305286,3052,305201,305204}, type=3, special="Focus Back Row", speed="", element={0}, weak_point={0,1}
