	[20]={ model="6110", name="Slasher Fiend", english="DAVIST", story="Members of the Coordinator Sect. There are many reasons to join them: seeking sustenance, seeking shelter, or simply wanting to vent dissatisfaction. [Slasher Fiend] clearly belongs to the latter. They are keen on blood, enjoy brutal killing, and like to dismember and display their prey in cruel ways—even within the Coordinators' camp, their actions have caused displeasure among many members.", hero_type=5, shadow="mon_archives_normal_6110.png", shadow_unlock="mon_archives_shadow_6110.png", dangerous=2, skill_list={298780,305883,305886,3058,305801}, type=3, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
