	[46]={ model="6109_d", name="Hammer Man·Lightning", english="DAVIST", story="Originally workers from the mining facilities, these individuals underwent grotesque transformation after exposure to the Void Expanse during the Anchor Panic. Their mutated epidermal growths and aberrant biological structures indicate Stage III infection. Though clumsy in movement, they retain terrifying proficiency with mining hammers—a grim reminder of their former profession. Unprepared travelers are strongly advised to disengage.", hero_type=5, shadow="mon_archives_normal_6109.png", shadow_unlock="mon_archives_shadow_6109.png", dangerous=2, skill_list={298780,313683,313686,3136,313601}, type=3, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
},
	[47]={ model="6116_d", name="[Workhound]·Lightning", english="Hillley", story="Made from old parts, this rough construct can follow simple AI commands, often appearing in large groups. Named for its resemblance to canines, the creator is unknown.", hero_type=1, shadow="mon_archives_normal_6116.png", shadow_unlock="mon_archives_shadow_6116.png", dangerous=1, skill_list={298280,313983,313986,3139}, type=2, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
},
	[48]={ model="6111", name="[Forest Ranger]", english="Alice", story="Low-intelligence robots first appeared in Selevie, designed to replace humans in forest patrols. People added simple decorations reflecting local Feature. They're short, not fast movers, but their arrows are speedy and hit targets precisely.", hero_type=5, shadow="mon_archives_normal_6111.png", shadow_unlock="mon_archives_shadow_6111.png", dangerous=2, skill_list={298680,314283,314286,3142,314201}, type=2, special="Focus Opposite", speed="", element={0}, weak_point={0,3}
},
	[49]={ model="6105_d", name="Mighty Maiden·Lightning", english="Corina", story="An infected human girl wears a comfortable, loose dress. She might have once been innocent and lively or gentle and introverted, but after contamination and mutation, she lost her humanity, now only violent and cruel. If you feel mercy for her, please handle her swiftly and try not to dirty her dress.", hero_type=1, shadow="mon_archives_normal_6105.png", shadow_unlock="mon_archives_shadow_6105.png", dangerous=1, skill_list={298380,314583,314586,3145}, type=3, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
},
	[50]={ model="6101_d", name="[Surveillance Fly]·Lightning", english="DAVIST", story="The TxP09 flight monitor produced by Divinelight Heavy Tech, Feature a design inspired by the appearance of a fly. Besides functioning as a monitor, it has some combat capabilities and can be deployed as a combat unit when necessary, although its combat strength is not high. Users are advised to use it cautiously.", hero_type=1, shadow="mon_archives_normal_6101.png", shadow_unlock="mon_archives_shadow_6101.png", dangerous=1, skill_list={298280,314883,314886,3148}, type=2, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
},
	[51]={ model="6117_d", name="Third Hand·Lightning", english="DAVIST", story="Members of the Coordinator Sect, likely low-ranked, are often seen in errands or simple combat missions. Don't overlook their combat abilities due to their rank; the code [Third Hand] shows how tricky and troublesome their third polluted hand is.", hero_type=5, shadow="mon_archives_normal_6117.png", shadow_unlock="mon_archives_shadow_6117.png", dangerous=2, skill_list={298780,315183,315186,3151,315101}, type=3, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
