	[52]={ model="6136", name="Wheeled Angel", english="DAVIST", story="Shogger resembling the ancient legendary creature 'Angel' from Taino Star, surrounded by abnormal flames, with three wheel-like objects spinning constantly. It seems to have some intelligence, able to emit sounds like [language,] but nobody understands it.", hero_type=5, shadow="mon_archives_normal_6136.png", shadow_unlock="mon_archives_shadow_6136.png", dangerous=2, skill_list={298880,315483,315486,3154,315401}, type=4, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
