	[53]={ model="6311", name="Ming", english="DAVIST", story="The head of the Anti-Skyborne Barriers organization [ULFT] in Lissugen, is bold and fiery, easily spotted with her striking red hair. Despite her youth, her subordinates call her [Big Sis.]", hero_type=6, shadow="mon_archives_normal_6311.png", shadow_unlock="mon_archives_shadow_6311.png", dangerous=3, skill_list={315780,315790,315783,315786,3157,315701,315704}, type=1, special="Focus Opposite", speed="", element={0}, weak_point={2,3}
