	[54]={ model="6104_g", name="Clawed Clerk·Quantum", english="Kalan Lisa", story="Mutants commonly found around fortress cities—The remnants of business suits, neckties, and leather shoes still visible on their twisted forms tell their tragic origin—these were once white-collar workers toiling in cubicles. Perhaps moments before contamination, they had just closed a deal, finalized a proposal, received a promotion... or were rushing home to loved ones... Until the unknown catastrophe struck, ending everything in an instant.", hero_type=1, shadow="mon_archives_normal_6104.png", shadow_unlock="mon_archives_shadow_6104.png", dangerous=1, skill_list={298380,316083,316086,3160}, type=3, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
},
	[55]={ model="6121_g", name="Sickle Claw·Quantum", english="DAVIST", story="Based on the remnants of the standard uniform, this type of mutant likely originally worked in security. They've lost self-awareness after being polluted, altering their biological Feature, with huge blade-like growths on their arms. Although they may appear agile, their moving speed is similar to a regular person, slower than expected. Their blade-arms can inflict serious damage easily, so upon encountering them, stay alert and escape.", hero_type=5, shadow="mon_archives_normal_6121.png", shadow_unlock="mon_archives_shadow_6121.png", dangerous=2, skill_list={298780,316383,316386,3163,316301}, type=3, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
},
	[56]={ model="6128_g", name="Disruptor·Quantum", english="DAVIST", story="A creature from the alien species known as [Shogger], resembles arthropods from Taino Star, supported by thin legs with a core-like trunk that emits energy interfering with electronics, similar to electromagnetic waves according to studies.", hero_type=1, shadow="mon_archives_normal_6128.png", shadow_unlock="mon_archives_shadow_6128.png", dangerous=1, skill_list={298480,316683,316686,3166}, type=4, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
