	[57]={ model="6102", name="Dachshund", english="DAVIST", story="A creature from the alien species known as [Shogger], resembles canine creatures from Taino Star. Covered in metal and stone-like unknown substances, they move in packs, their paws like steel blades, moving unpredictably and causing great harm.", hero_type=5, shadow="mon_archives_normal_6102.png", shadow_unlock="mon_archives_shadow_6102.png", dangerous=2, skill_list={298880,316983,316986,3169,316901}, type=4, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
