	[58]={ model="6119", name="Box Scorpion", english="Bianno", story="A creature from the alien species known as [Shogger], looks like the scorpion from Taino Star, but more like a box with a long tail. The sting from its pustule-like tail is poisonous, causing unbearable pain and possibly death.", hero_type=1, shadow="mon_archives_normal_6119.png", shadow_unlock="mon_archives_shadow_6119.png", dangerous=1, skill_list={298480,300086,3172}, type=4, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
