	[59]={ model="6118", name="Serpent Drake", english="DAVIST", story="A creature from the alien species known as [Shogger], looks like a legendary [flying snake.] It seems to have high intellect, not attacking recklessly, striking at the perfect moment, fitting the stereotype of a snake or dragon.", hero_type=5, shadow="mon_archives_normal_6118.png", shadow_unlock="mon_archives_shadow_6118.png", dangerous=2, skill_list={298880,317583,317586,3175,317501}, type=4, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
