	[61]={ model="6123", name="Wolf Hunter", english="DAVIST", story="A creature from the alien species known as [Shogger], resembles canine creatures from Taino Star with short limbs and large [heads] surrounded by complex structures. Reports from battles suggest the head is their [death point.]", hero_type=5, shadow="mon_archives_normal_6123.png", shadow_unlock="mon_archives_shadow_6123.png", dangerous=2, skill_list={298880,318183,318186,3181,318101}, type=4, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
