	[73]={ model="6301", name="Iron Thorn", english="DAVIST", story="Members of the Coordinator Sect, low-ranked, are often put on advance sabotage tasks. Contamination has resulted in severe mutations on various bodily parts, including but not limited to skin deformities and abnormal surface structures—arms sprouting thorn-like parts. They retain human consciousness but suffer from intense mental contamination, showing long-term insanity and pathological behavior, with aggressive and destructive tendencies.", hero_type=6, shadow="mon_archives_normal_6301.png", shadow_unlock="mon_archives_shadow_6301.png", dangerous=3, skill_list={400880,400890,400883,400886,4008,400801,400804}, type=3, special="Focus Opposite Front Row", speed="", element={0}, weak_point={1,4}
