	[74]={ model="6302", name="Sword Angel", english="DAVIST", story="A Shogger slightly resembling angels from ancient tales, attacking with a [great sword] made of the same material as its body. It appears to have intelligence, emitting rhythmical sounds from its [head.] Some say it's Shogger language but there's been no proof.", hero_type=6, shadow="mon_archives_normal_6302.png", shadow_unlock="mon_archives_shadow_6302.png", dangerous=3, skill_list={401180,401190,401183,401186,4011,401101,401104}, type=4, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
