	[75]={ model="6304", name="Peril Beast", english="DAVIST", story="A creature from the alien species known as [Shogger] somewhat resembles a tiger from Taino Star, missing visible facial Feature but with a mouth that absorbs energy. Its four [tails] can emit energy and heat rays, causing great destruction. When attacked directly, it forms a protective barrier; breaking through requires much stronger force, making it one of the more troublesome Shogger types known.", hero_type=6, shadow="mon_archives_normal_6304.png", shadow_unlock="mon_archives_shadow_6304.png", dangerous=3, skill_list={401480,401490,401483,401486,4014,401401,401404}, type=4, special="Focus Front Row", speed="", element={0}, weak_point={2,5}
