	[76]={ model="6106", name="Bio-Enhanced·Male", english="DAVIST", story="A bio-enhanced human illegally modified multiple times, the modifier inserted many experimental mechanical components not approved for use. Though it severely increased combat ability, it greatly damaged normal human body structure. Due to the modifier's neglect for body restoration, it's held together by bandages—[as long as you're dressed well, no one will know what you're,] the modifier advised the experimenter.", hero_type=5, shadow="mon_archives_normal_6106.png", shadow_unlock="mon_archives_shadow_6106.png", dangerous=2, skill_list={298580,401783,401786,4017,401701}, type=1, special="Focus Front Row", speed="", element={0}, weak_point={0,3}
