	[77]={ model="6108", name="Bio-Enhanced·Female", english="DAVIST", story="A bio-enhanced human illegally modified multiple times, modified with many out-of-spec components increasing physique. To keep a human appearance due to the modifier's personal taste, various illegal recovery liquids were injected. The face was intentionally damaged beyond recognition, so bandages are worn constantly.", hero_type=5, shadow="mon_archives_normal_6108.png", shadow_unlock="mon_archives_shadow_6108.png", dangerous=2, skill_list={298580,402083,402086,4020,402001}, type=1, special="Focus Opposite Front Row", speed="", element={0}, weak_point={0,3}
